static inline void tilespmm_policy_select(
    const double *features, float *gamma, float *delta, int index)
{
    while (index >= 0) {
        const tilespmm_policy_node *node = &tilespmm_shared_nodes[index];
        float value = (float)features[node->feature + 2];
        int left = isnan(value) ? (node->missing_left_mask & 1) : value < node->cut;
        if (left) {
            if (node->left_feature < 0) {
                index = node->child0;
            } else {
                value = (float)features[node->left_feature + 2];
                left = isnan(value) ? (node->missing_left_mask & 2) : value < node->left_cut;
                index = left ? node->child0 : node->child1;
            }
        } else {
            if (node->right_feature < 0) {
                index = node->child2;
            } else {
                value = (float)features[node->right_feature + 2];
                left = isnan(value) ? (node->missing_left_mask & 4) : value < node->right_cut;
                index = left ? node->child2 : node->child3;
            }
        }
    }
    int action = -1 - index;
    *gamma = tilespmm_model_candidates[action][0];
    *delta = tilespmm_model_candidates[action][1];
}
static inline void predictparams_fp16(const double *features, float *gamma, float *delta)
{
    tilespmm_policy_select(features, gamma, delta, 2512);
}
static inline void predictparams_tf32(const double *features, float *gamma, float *delta)
{
    tilespmm_policy_select(features, gamma, delta, 3420);
}
